var r=[{title:`Fördelar`,text:`Varje hand bär sin egen vikt, vilket gör ensidigt arbete praktiskt och ger grepp i vinklar som en fast stång kanske inte tillåter. En enarmsrodd eller enarmspress kan visa skillnader i kontroll mellan dina sidor. Hantlar passar ofta bättre i små utrymmen än en hel skivstångsuppsättning, även om stegen mellan vikterna kan vara stora eller urvalet begränsat.`},{title:`Välj din vikt`,text:`Välj ett par eller en enskild hantel som låter dig nå dina målrepetitioner med jämn rörelse och några repetitioner kvar i reserv. Som nybörjare kan du behöva olika vikter för rodd, curl och press. Om nästa vikt upp är för tung, öka först repetitioner, rörelseomfång eller kontroll med den lättare.`},{title:`Ta dig säkert i position`,text:`För en bänkpress sätter du dig med hantlarna hållna stadigt nära låren, lutar dig bakåt under kontroll och för vikterna på plats utan att kasta dem. För stående lyft tar du upp vikterna med ben och bål i ett stabilt läge. Tappa inte vikter där de kan studsa mot dina fötter, skada golvet eller träffa någon.`},{title:`Vanliga användningar`,text:`Goblet-knäböj och rumänsk marklyft med hantlar tränar underkroppen, stödda rodd och pressar täcker överkroppen, och bärande bygger grepp och bålkontroll. Om du bara har en hantel kan du använda den till ensidiga rörelser.`},{title:`Så använder du TrainUp`,text:`Ange vikterna på de hantlar du äger i Profil. Ditt program väljer övningar som passar din utrustning, ditt utrymme och din takhöjd. Det föreskriver inga vikter, så du väljer belastningen. Om du antecknar dina vikter efter ett pass, skriv dem på samma sätt varje gång, till exempel ”12 kg per hand”.`}];var n=[{label:`Mayo Clinic: fria vikter jämfört med maskinvikter`,url:`https://www.augustahealth.com/answer/weight-training-free-weights-vs-machine-weights/`},{label:`ACE:s övningsbibliotek`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Mayo Clinic: teknik vid styrketräning (2026)`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`}];var a={sections:r,sources:n};export{a as default,r as sections,n as sources};